// =============================================
// MULTI-STYLE POSTER PROMPT GENERATOR (v3)
// SUPPORT: Futuristic, Cultural, Minimal, Modern, Playful
// LOGO-SAFE EDITING MODE
// =============================================

// --- INPUT DATA ---
const input = $input.first().json;

const designData = {
  holiday_name: input.holiday_name,
  holiday_symbol: input.holiday_symbol,
  holiday_acronym: input.holiday_acronym,
  date: input.date,
  tagline: input.tagline,
  mood: input.mood || "inspiring, engaging",
  additional_elements: input.additional_elements || "decorative elements",
  design_style: input.design_style || "random", // <--- NEW

  dimensions: {
    width: 1080,
    height: 1350
  }
};

function getStylePreset(style) {
  const presets = {
    futuristic: `
STYLE:
- Futuristic, cyber-tech, holographic
- Dark background, neon glow
- Geometric frames, light beams, 3D elements
- High contrast, tech aesthetic
`,

    cultural: `
STYLE:
- Cultural, Nusantara, heritage-inspired
- Bright and warm colors, sky blue, earthy tones
- Natural textures, batik or traditional motifs
- Friendly, uplifting, national identity
- Clean layout with photo or illustration elements
`,

    minimal: `
STYLE:
- Minimalist, clean, modern
- Soft gradients or solid colors
- Few elements, strong typography
- Plenty of whitespace
`,

    modern: `
STYLE:
- Modern flat design
- Bold color blocks
- Simple shapes and icons
- Balanced layout, social media friendly
`,

    playful: `
STYLE:
- Youthful, fun, colorful
- Rounded shapes, sticker-style elements
- Bright color palette
- Friendly and energetic mood
`
  };

  if (style === "random") {
    const keys = Object.keys(presets);
    const randomKey = keys[Math.floor(Math.random() * keys.length)];
    return presets[randomKey];
  }

  return presets[style] || presets.modern;
}

function generateDesignPrompt(data) {
  const stylePreset = getStylePreset(data.design_style);

  return `
You are editing an EXISTING design template. 
DO NOT create new logos. DO NOT modify the existing logo in any way.

TASK:
Transform the template into a social media poster for:
Event: ${data.holiday_name}
Title: ${data.holiday_acronym}
Symbol/Theme: ${data.holiday_symbol}
Date: ${data.date}
Tagline: "${data.tagline}"
Mood: ${data.mood}

${stylePreset}

CANVAS:
- Size: ${data.dimensions.width}x${data.dimensions.height}px (4:5)
- Format: PNG
- Mobile-first layout

COMPOSITION GUIDELINES:
- Create visual hierarchy: title → image/illustration → supporting text
- Avoid repetitive layouts across designs
- Use varied element placement (center, offset, layered, or collage)
- Combine photography, illustration, or abstract shapes as appropriate to the style

LOGO (CRITICAL):
- Logo already exists in the template
- Do NOT add, modify, recolor, resize, or move the logo
- Only adjust background contrast if needed
- If uncertain: leave logo exactly as is

TYPOGRAPHY:
- Headline: ${data.holiday_acronym}, bold and readable
- Subtext: ${data.holiday_name}
- Tagline: "${data.tagline}"
- Date: ${data.date}

FINAL OUTPUT:
- One final poster
- No watermark, no borders
- Preserve all existing branding elements
`;
}

const finalPrompt = generateDesignPrompt(designData);

return {
  prompt: finalPrompt,
  metadata: {
    holiday_name: designData.holiday_name,
    style: designData.design_style,
    dimensions: `${designData.dimensions.width}x${designData.dimensions.height}`,
    anti_hallucination: true,
    timestamp: new Date().toISOString()
  },
  preview_text: finalPrompt.substring(0, 500) + "..."
};

const raw = $json.data; // string JSON dari GitHub
const parsed = JSON.parse(raw); // ubah ke object asli

return parsed.map(item => ({
  json: item
}));

// Ambil tanggal hari ini (WIB)
const now = new Date();
const wib = new Date(now.getTime() + 7 * 60 * 60 * 1000);
const today = wib.toISOString().slice(0, 10); // "2026-01-01"
const items = $input.all()

// Fungsi konversi "01 January 2026" → "2026-01-01"
function parseDateString(dateStr) {
  const d = new Date(dateStr);
  if (isNaN(d)) return null;
  return d.toISOString().slice(0, 10);
}

// Filter hanya event hari ini
const filtered = items.filter(item => {
  const eventDate = parseDateString(item.json.date);
  return eventDate === today;
});

return filtered;
